#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=9
ENV_FILE=".env.production"
umask 077
[[ -f "$ENV_FILE" ]] || { warn "Run bun run production:prepare first."; exit 1; }
mkdir -p infra/secrets
chmod 0700 infra/secrets
banner "Consumit: OVH + AWS private account setup"

stage "AWS: verify credits and Free account deadline"
open_url "https://console.aws.amazon.com/billing/home#/credits"
step "Verify your actual remaining credit, expiry, eligible services and Free account deadline."
step "Stay Free for now. No upgrade is performed by this wizard."
step "Use the earlier expiry for AWS_CREDIT_EXPIRES_AT; the monitor also checks the API plan expiry."
ask AWS_CREDIT_EXPIRES_AT "Paste that expiry as an ISO date (YYYY-MM-DD):"
write_env AWS_CREDIT_EXPIRES_AT "$AWS_CREDIT_EXPIRES_AT"
pause "Credit eligibility and SES/S3 availability confirmed? Press Enter."

stage "OVH: provision the selected VPS"
open_url "https://www.ovhcloud.com/en-ma/vps/"
step "Select the approved Canada VPS. Prefer Ubuntu 24.04 LTS for this first release."
step "Confirm 158.64 MAD/month including VAT and included backups in the final order."
confirm "Proceed with the VPS purchase in your own browser?" || exit 0
pause "Finish payment and provisioning, then press Enter."
open_url "https://www.ovh.com/manager/"
ask VPS_IP "Paste its IP:"
ask VPS_SSH_USER "Paste its SSH username (no password):"
write_env VPS_IP "$VPS_IP"
write_env VPS_SSH_USER "$VPS_SSH_USER"

stage "AWS: choose backup bucket and budget destination"
open_url "https://ca-central-1.console.aws.amazon.com/s3/home?region=ca-central-1"
step "Choose a globally unique bucket name. The reviewed Terraform creates it with versioning and Object Lock."
ask AWS_BACKUP_BUCKET "Bucket name:"
write_env AWS_BACKUP_BUCKET "$AWS_BACKUP_BUCKET"
node scripts/provisioning.mjs s3
open_url "https://console.aws.amazon.com/billing/home#/budgets"
ask AWS_BUDGET_EMAIL "Operator email for the gross-usage alerts at USD 2 and USD 5:"
write_env AWS_BUDGET_EMAIL "$AWS_BUDGET_EMAIL"
note "Give this email and bucket name to the agent for Terraform variables; never include keys."
pause "Press Enter after you have authenticated the provisioning profile privately."
# Terraform plan/apply is performed separately after the owner verifies credit
# eligibility and the agent presents the exact resources and cost assumptions.

stage "Cloudflare: zone, Tunnel and temporary launch access"
open_url "https://dash.cloudflare.com/"
step "Add consumit.online to Cloudflare Free and apply its assigned nameservers at your registrar."
step "Authenticate the scoped Terraform token privately; the agent creates DNS, Tunnel and Free edge rules."
step "Keep public_registration_enabled=false in Terraform and add your tester IPs to launch_tester_ips until the launch gates pass."
open_url "https://one.dash.cloudflare.com/"
step "After the Tunnel exists, copy its connector token into the hidden prompt."
ask_secret TUNNEL_TOKEN "Tunnel connector token:"
if [[ -z "$TUNNEL_TOKEN" && -f infra/secrets/tunnel-token ]]; then TUNNEL_TOKEN="$(cat infra/secrets/tunnel-token)"; fi
[[ -n "$TUNNEL_TOKEN" ]] || { warn "A real connector token is required."; exit 1; }
printf '%s\n' "$TUNNEL_TOKEN" > infra/secrets/tunnel-token
chmod 0644 infra/secrets/tunnel-token
pause "DNS and temporary tester access configured? Press Enter."

stage "AWS: install separate least-privilege credentials"
open_url "https://console.aws.amazon.com/iam/home#/users"
step "After Terraform creates the users, open each user's Security credentials and create an access key for an application outside AWS."
step "Use consumit-email, consumit-backup, consumit-feedback, consumit-credit-monitor, and consumit-recovery."
step "Keep recovery credentials offline after the launch restore drill; they are not mounted in the API."
for role in ses backup feedback credit recovery; do
  saved_env="$ENV_FILE"
  ENV_FILE="infra/secrets/$role.capture.env"
  say "Credential role: $role"
  ask_secret AWS_ACCESS_KEY_ID "Access key ID:"
  ask_secret AWS_SECRET_ACCESS_KEY "Secret access key:"
  if [[ -z "$AWS_ACCESS_KEY_ID" && -z "$AWS_SECRET_ACCESS_KEY" && -f "infra/secrets/$role-aws.json" ]]; then
    note "Kept the existing private credential file."
    ENV_FILE="$saved_env"
    continue
  fi
  write_env AWS_ACCESS_KEY_ID "$AWS_ACCESS_KEY_ID"
  write_env AWS_SECRET_ACCESS_KEY "$AWS_SECRET_ACCESS_KEY"
  node scripts/provisioning.mjs credentials "$role" < "$ENV_FILE"
  rm -- "$ENV_FILE"
  ENV_FILE="$saved_env"
  unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY
done
pause "Separate credentials saved. Press Enter."

stage "SES: DNS, pricing and production access"
open_url "https://ca-central-1.console.aws.amazon.com/ses/home?region=ca-central-1"
step "Publish Terraform's dns_records in Cloudflare. SES DKIM CNAME records must be DNS-only."
step "Keep existing MX records for incoming mail. MAIL FROM uses bounce.consumit.online."
step "Verify consumit.online, DKIM and MAIL FROM; confirm auth@consumit.online as the sender."
step "Select the a la carte email pricing option, not the default Essentials bundle."
step "Request production access for transactional authentication email and quota of 10,000 recipients/day and 10 sends/second."
step "Confirm account-level bounce/complaint suppression and the consumit-auth feedback destination."
ask SES_FEEDBACK_QUEUE_URL "Paste Terraform's feedback_queue_url:"
write_env SES_FEEDBACK_QUEUE_URL "$SES_FEEDBACK_QUEUE_URL"
pause "Press Enter after approval and delivery to a controlled test inbox."

stage "Telegram: operator alert destination"
open_url "https://t.me/BotFather"
step "Create your own alert bot, then start it in the private operator chat or add it to the operator group."
ask_secret TELEGRAM_BOT_TOKEN "Paste the bot token:"
if [[ -z "$TELEGRAM_BOT_TOKEN" && -f infra/secrets/telegram-token ]]; then TELEGRAM_BOT_TOKEN="$(cat infra/secrets/telegram-token)"; fi
[[ -n "$TELEGRAM_BOT_TOKEN" ]] || { warn "A real Telegram bot token is required."; exit 1; }
printf '%s\n' "$TELEGRAM_BOT_TOKEN" > infra/secrets/telegram-token
open_url "https://core.telegram.org/bots/api#getupdates"
step "Use getUpdates privately to identify the numeric chat ID; never paste the full response into chat."
ask TELEGRAM_CHAT_ID "Numeric chat ID (groups normally have a negative ID):"
write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
node scripts/provisioning.mjs telegram
unset TELEGRAM_BOT_TOKEN
pause "Telegram destination prepared. Press Enter."

stage "Cloudflare: independent outage monitor"
open_url "https://dash.cloudflare.com/"
step "Create a Workers KV namespace for consumit-external-uptime under Workers & Pages / KV."
ask CF_UPTIME_KV_ID "Paste the KV namespace ID:"
write_env CF_UPTIME_KV_ID "$CF_UPTIME_KV_ID"
note "The agent deploys the separate cron Worker with private Telegram secrets; it runs every five minutes."
pause "External monitor account access ready? Press Enter."

stage "Offline recovery and launch checks"
step "Keep an encrypted monthly recovery copy outside AWS and OVH, including repository passwords, CA and deployment configuration."
step "The agent installs the fresh production database, certificates, migrations, backup timers and credit monitoring."
step "Keep temporary tester access until real SES, restore, alert, HTTPS playback and 50-session load checks pass."
step "Only then remove the temporary access restriction and open the public site."
step "Switch AWS to Paid when fewer than 30 days remain or credit drops below USD 20; confirm it before suspension."
pause "Press Enter to finish private account setup."
finish
